-- Draft inventory schema, depends on 001_foundation. No posting API yet.
begin;
create table erp.lots(id uuid primary key default gen_random_uuid(), item_id uuid not null references erp.items, lot_code text not null, manufactured_on date, expires_on date, quality_status text not null default 'pending' check(quality_status in ('pending','released','quarantine','rejected')), unique(item_id,lot_code), unique(id,item_id), check(expires_on is null or manufactured_on is null or expires_on>=manufactured_on));
create table erp.stock_documents(id uuid primary key default gen_random_uuid(), source_type text not null, source_id text not null, idempotency_key text unique not null, status text not null default 'draft' check(status in ('draft','posted','reversed')), reversal_of uuid unique references erp.stock_documents, created_at timestamptz not null default now(), posted_at timestamptz, created_by uuid references auth.users);
create table erp.stock_moves(id bigint generated always as identity primary key, document_id uuid not null references erp.stock_documents, item_id uuid not null references erp.items, lot_id uuid not null, location_id uuid not null references erp.locations, quantity_delta numeric(18,6) not null check(quantity_delta<>0), value_delta numeric(24,8) not null, foreign key(lot_id,item_id) references erp.lots(id,item_id));
create table erp.stock_balances(item_id uuid not null references erp.items, lot_id uuid not null, location_id uuid not null references erp.locations, quantity numeric(18,6) not null check(quantity>=0), primary key(item_id,lot_id,location_id), foreign key(lot_id,item_id) references erp.lots(id,item_id));
create table erp.item_valuation(item_id uuid primary key references erp.items, quantity numeric(18,6) not null check(quantity>=0), total_value numeric(24,8) not null check(total_value>=0), check(quantity<>0 or total_value=0));
create table erp.reservations(id uuid primary key default gen_random_uuid(), item_id uuid not null, lot_id uuid not null, location_id uuid not null, quantity numeric(18,6) not null check(quantity>0), source_type text not null, source_id text not null, status text not null default 'active' check(status in ('active','released','consumed')), foreign key(item_id,lot_id,location_id) references erp.stock_balances);
create table erp.lot_genealogy(parent_lot_id uuid references erp.lots, child_lot_id uuid references erp.lots, document_id uuid references erp.stock_documents, input_quantity numeric(18,6) not null check(input_quantity>0), primary key(parent_lot_id,child_lot_id,document_id), check(parent_lot_id<>child_lot_id));
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='erp' loop execute format('alter table erp.%I enable row level security',t.tablename); end loop; end $$;
commit;
-- Required before use: atomic posting with locks, reservation checks, QC/expiry checks,
-- immutable posted rows, genealogy cycle detection, balanced accounting integration.
